/** The capabilities a user can turn off for every adapter, and a client declares. */
export const KOMLA_CAPABILITIES = [
  { id: 'agent.launch.workspace', description: 'Launch an AI coding agent in a new isolated Komla workspace.' },
  { id: 'agent.launch.tab', description: 'Launch an AI coding agent in a new tab in the current workspace.' },
  { id: 'workspace.title', description: 'Set the title and description shown for the current workspace.' },
  { id: 'workspace.snooze', description: 'Snooze the current workspace until a time or its next notification. Waking it stays allowed.' },
  { id: 'workspace.tag', description: 'Tag the current workspace to say what it waits on, such as "Waiting for review", or take its tag off.' },
  { id: 'workspace.trash', description: 'Move the current workspace to the Trash once the agent’s turn ends, stopping its terminals. The user can restore it for 7 days.' },
  { id: 'workspace.link', description: 'Link the current workspace to other workspaces, so agents can read and edit their files through its linked-workspaces folder, or unlink them.' },
  { id: 'folder.open', description: 'Open a folder on this computer in Komla, as its own workspace.' },
  { id: 'status.set', description: 'Show a short status, such as test results or a pull request link, in the status bar while the current workspace is open.' },
  { id: 'terminal.read', description: 'List the terminals in the current workspace, read what one shows, and wait for its agent to finish or need you (komla terminals, read and wait).' },
  { id: 'terminal.send', description: 'Type a message into another terminal in the current workspace and submit it, as to steer an agent another agent started. It never answers an agent waiting for you unless forced.' },
  { id: 'preview.open', description: 'Offer the user a page, such as a dev server, or open it in the workspace\'s browser.' },
] as const;

export type KomlaCapability = (typeof KOMLA_CAPABILITIES)[number]['id'];

